-- Owner-approved final stock identities only. Existing master versions, rate keys,
-- document snapshots, stock movements, costing and payment rows are unchanged.
-- The effective catalogue reads current commercial details from the original ID.
CREATE TABLE inventory_final_stock_ids (
 item_id text PRIMARY KEY, source_live_id text,
 description text NOT NULL, category text NOT NULL, units jsonb NOT NULL,
 approved_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE inventory_final_stock_aliases (
 old_id text NOT NULL, item_id text NOT NULL REFERENCES inventory_final_stock_ids(item_id),
 PRIMARY KEY(old_id,item_id)
);
CREATE TRIGGER immutable_final_stock_ids BEFORE UPDATE OR DELETE ON inventory_final_stock_ids FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_final_stock_aliases BEFORE UPDATE OR DELETE ON inventory_final_stock_aliases FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
