INSERT INTO inventory_final_stock_aliases(old_id,item_id) SELECT x->>'oldId',jsonb_array_elements_text(x->'finalIds') FROM jsonb_array_elements($finalids$[{"oldId":"CH-CBL-Cont 23/76 2C","finalIds":["CH-CBL-CNT-1.5MM/2C"]},{"oldId":"CH-BRK-AC-100A/4P-CC","finalIds":["CH-BRK-AC-100A/4P-MCCB"]},{"oldId":"CH-PCS-HYB-SP-006","finalIds":["CH-PCS-HYB-1P-006"]},{"oldId":"CH-DC Fuse 20-AMP","finalIds":["CH-FUSE-20A"]},{"oldId":"CH-SOLAR BOX-18x24","finalIds":["CH-SOLARBOX-18*24"]},{"oldId":"CH-CBL-ERT-2.5MM/1CP","finalIds":["CH-CBL-ERT-2.5MM/1C-PK"]},{"oldId":"CH-CBL-ERT-6MM/1C-RP","finalIds":["CH-CBL-ERT-6MM/1C-PK"]},{"oldId":"CH-Cable-DC-6MM","finalIds":["CH-CBL-DC-6MM/1C-R/PK","CH-CBL-DC-6MM/1C-B/PK"]},{"oldId":"CH-11 WAY-DB","finalIds":["CH-11WAY-DB"]},{"oldId":"CH-BRK-DC-63A-2P","finalIds":["CH-BRK-DC-63A/2P"]},{"oldId":"CH-IO MODULE","finalIds":["CH-IOMODULE"]}]$finalids$::jsonb) x;

CREATE VIEW inventory_catalogue_recorded AS
 SELECT DISTINCT ON(item_id) * FROM inventory_catalogue_versions ORDER BY item_id,version DESC;
-- Retain the existing column names/types for all dependent queries.
CREATE OR REPLACE VIEW inventory_catalogue_current AS
 SELECT c.item_id,c.version,
   c.payload || jsonb_build_object('finalStockId',f.item_id IS NOT NULL,
     'stockUnits',coalesce(f.units,'[]'::jsonb),'stockDescription',f.description,
     'stockIdentityStatus',CASE WHEN f.item_id IS NOT NULL THEN 'Final Sheet ID' ELSE 'Commercial / service reference; stock link pending' END) AS payload,
   c.rate_key,c.created_at
 FROM inventory_catalogue_recorded c
 LEFT JOIN inventory_final_stock_ids f ON f.item_id=c.item_id
 WHERE NOT EXISTS(SELECT 1 FROM inventory_final_stock_aliases a WHERE a.old_id=c.item_id AND a.item_id<>c.item_id)
 UNION ALL
 SELECT f.item_id,coalesce(c.version,1),
   coalesce(c.payload,jsonb_build_object(
      'technicalDescription',f.description,'commercialDescription',f.description,
      'category',f.category,'itemGroup',CASE
       WHEN f.category IN ('AC cables','DC cables','Earthing cables','Communication cables') THEN 'Cables'
       WHEN f.category='Solar panels' THEN 'Solar Panels'
       WHEN f.category='AC switchgear' THEN 'AC Switchgear'
       WHEN f.category='DC switchgear' THEN 'DC Switchgear'
       WHEN f.category='DB boxes' THEN 'AC / DC Boxes' ELSE f.category END,
      'brandCategory',CASE WHEN f.item_id LIKE '%/PK' OR f.item_id LIKE '%-PK' THEN 'Pakistan Cables'
       WHEN f.item_id LIKE '%/NA' OR f.item_id LIKE '%-NA' THEN 'Newage Cables'
       WHEN f.item_id LIKE '%/LCL' THEN 'All other cables' ELSE 'Unconfirmed' END,
      'unit',f.units->>0,'itemType','Stock','status','Needs review',
      'reviewNotes','Final Sheet ID approved. Commercial/rate link pending; no rate or stock balance imported.'))
    || jsonb_build_object('itemId',f.item_id,'finalStockId',true,
       'stockUnits',f.units,'stockDescription',f.description,
       'legacyItemId',f.source_live_id,'rateLinkPending',c.item_id IS NULL,
       'stockIdentityStatus','Final Sheet ID') AS payload,
   c.rate_key,coalesce(c.created_at,f.approved_at)
 FROM inventory_final_stock_ids f
 LEFT JOIN inventory_catalogue_recorded c ON c.item_id=f.source_live_id
 WHERE NOT EXISTS(SELECT 1 FROM inventory_catalogue_recorded direct WHERE direct.item_id=f.item_id);

-- One-to-one aliases resolve to final IDs. Combined red/black aliases are held
-- for explicit colour selection instead of pointing arbitrarily to one colour.
CREATE VIEW inventory_item_aliases_current AS
 SELECT a.alias,coalesce(f.item_id,a.item_id) AS item_id
 FROM inventory_item_aliases a
 LEFT JOIN (SELECT old_id,min(item_id) AS item_id FROM inventory_final_stock_aliases GROUP BY old_id HAVING count(*)=1) f ON f.old_id=a.item_id
 WHERE NOT EXISTS(SELECT 1 FROM inventory_final_stock_aliases amb WHERE amb.old_id=a.item_id GROUP BY old_id HAVING count(*)>1)
   AND NOT EXISTS(SELECT 1 FROM inventory_final_stock_aliases direct WHERE direct.old_id=a.alias)
 UNION ALL
 SELECT old_id,min(item_id) FROM inventory_final_stock_aliases GROUP BY old_id HAVING count(*)=1;
